public class Colaborador implements Identificavel,Remuneravel,Autenticavel { private final String nome,cpf; private final double salario; private final String senha; public Colaborador(String n,String c,double s,String p){nome=n;cpf=c;salario=s;senha=p;} public String getNome(){return nome;} public String getCpf(){return cpf;} public double calcularSalario(){return salario;} public boolean autenticar(String s){return senha.equals(s);} }
